import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D31cdF9L.js";import"./chunks/assets.DM0yF35s.js";var i=JSON.parse(`{"title":"Choosing a Format","description":"","frontmatter":{},"headers":[],"relativePath":"guide/formats.md","filePath":"guide/formats.md"}`),a={name:`guide/formats.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="choosing-a-format" tabindex="-1">Choosing a Format <a class="header-anchor" href="#choosing-a-format" aria-label="Permalink to “Choosing a Format”">​</a></h1><p>GraphScribe can export the same asset in four different formats. They each serve a different purpose. Pick the one that matches what you&#39;re trying to do. You choose the format in the export dialog&#39;s <strong>Format</strong> combo (you can set a <a href="/GraphScribe-Documentation/guide/settings.html">default format</a>).</p><p><img src="/GraphScribe-Documentation/img/export-dialog.png" alt="The export dialog with the Format combo" width="1800" height="908"></p><table tabindex="0"><thead><tr><th>Format</th><th>File extension</th><th>Best for</th><th style="text-align:center;">Readable by humans?</th><th style="text-align:center;">Readable by AI/tools?</th></tr></thead><tbody><tr><td><strong>Markdown</strong></td><td><code>.md</code></td><td>AI agents, code review, documentation, PRs</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td><strong>Graphify</strong></td><td><code>.graphify.json</code></td><td>Knowledge graphs and AI agents</td><td style="text-align:center;">Somewhat</td><td style="text-align:center;">Yes</td></tr><tr><td><strong>Mermaid</strong></td><td><code>.mmd</code></td><td>Diagrams that render on GitHub, GitLab, Notion</td><td style="text-align:center;">Yes (as a diagram)</td><td style="text-align:center;">Yes</td></tr><tr><td><strong>JSON</strong></td><td><code>.json</code></td><td>Custom tools and scripts</td><td style="text-align:center;">Not really</td><td style="text-align:center;">Yes</td></tr></tbody></table><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to “Markdown”">​</a></h2><p>The human-friendly option. Variables, functions, graphs, macros, delegates, class references, and widget trees become clean Markdown sections. This is the format you&#39;ll read the most. See <a href="/GraphScribe-Documentation/guide/markdown-output.html">Markdown Output</a>.</p><h2 id="graphify" tabindex="-1">Graphify <a class="header-anchor" href="#graphify" aria-label="Permalink to “Graphify”">​</a></h2><p>A knowledge graph format designed for <strong>AI and graph databases</strong>. Unlike the other formats, Graphify:</p><ul><li>gives every Blueprint, function, and class a <strong>stable ID</strong> (<code>bp:</code> / <code>fn:</code> / <code>cls:</code>),</li><li>records <strong>links between assets</strong> (<code>calls</code>, <code>defines</code>, <code>uses</code>, plus per-asset <code>contains</code>),</li><li>can merge every exported file into one <strong>project-wide</strong> graph (<code>ProjectLinkage.graphify.json</code>).</li></ul><p>This is what lets AI answer &quot;who calls this function?&quot; across your whole project. See <a href="/GraphScribe-Documentation/guide/graphify-output.html">Graphify: AI-Ready Graphs</a>.</p><h2 id="mermaid" tabindex="-1">Mermaid <a class="header-anchor" href="#mermaid" aria-label="Permalink to “Mermaid”">​</a></h2><p>A flowchart description that renders as a diagram anywhere Mermaid is supported. GitHub READMEs, GitLab, Notion, and more. Great for putting a visual of a Blueprint graph or widget hierarchy into a document. See <a href="/GraphScribe-Documentation/guide/mermaid-output.html">Mermaid Diagrams</a>.</p><h2 id="json" tabindex="-1">JSON <a class="header-anchor" href="#json" aria-label="Permalink to “JSON”">​</a></h2><p>A complete, structured dump of everything in the asset. Nodes, pins, edges, variables, class refs, widget tree, diagnostics, and more. Use this if you&#39;re writing your own tooling to process Blueprint data. It&#39;s verbose and not meant to be read by people. See <a href="/GraphScribe-Documentation/guide/json-output.html">JSON Output</a>.</p><h2 id="same-content-in-every-format" tabindex="-1">Same content in every format? <a class="header-anchor" href="#same-content-in-every-format" aria-label="Permalink to “Same content in every format?”">​</a></h2><p>Almost. Every format exports the full asset, but some things are format-specific:</p><ul><li><strong>Graphify</strong> filters out Kismet utility noise (Branch, Sequence, Get/Set nodes, <code>Kismet*Library</code> calls) so the graph keeps only gameplay linkage. Markdown/Mermaid/JSON keep the full node set.</li><li><strong>Selection exports</strong> contain only the selected nodes and omit variables, widget trees, and class references in every format.</li><li><strong>DataTables</strong> are never exported in any format.</li></ul><h2 id="which-one-should-i-use" tabindex="-1">Which one should I use? <a class="header-anchor" href="#which-one-should-i-use" aria-label="Permalink to “Which one should I use?”">​</a></h2><ul><li><strong>Writing docs or reviewing code</strong> → Markdown</li><li><strong>Feeding AI or a knowledge base</strong> → Graphify</li><li><strong>Showing a visual diagram</strong> → Mermaid</li><li><strong>Building a tool</strong> → JSON</li></ul>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};